// redacts all configured sensitive HTTP headers before including them in debug
// output. This prevents accidental exposure of credentials in Terraform logs.
func TestDebugResponseRedactsSensitiveHeaders(t *testing.T) {
	sensitiveHeaders := []string{"Authorization", "X-Api-Key", "X-Custom-Key", "X-Custom-Secret"}

	if len(sensitiveHeaders) == 0 {
		t.Skip("No sensitive headers configured")
	}

	for _, header := range sensitiveHeaders {
		t.Run(header, func(t *testing.T) {
			// Create a mock request with the sensitive header set
			req, err := http.NewRequest("GET", "http://example.com/test", nil)
			if err != nil {
				t.Fatalf("Failed to create request: %v", err)
			}
			req.Header.Set(header, "secret-value-12345")

			// Create a mock response
			resp := &http.Response{
				Status:     "200 OK",
				StatusCode: 200,
				Proto:      "HTTP/1.1",
				ProtoMajor: 1,
				ProtoMinor: 1,
				Header:     make(http.Header),
				Body:       io.NopCloser(bytes.NewBufferString(`{"status":"ok"}`)),
				Request:    req,
			}

			// Call debugResponse
			output := debugResponse(resp)

			// Verify the secret value is NOT in the output
			if strings.Contains(output, "secret-value-12345") {
				t.Errorf("debugResponse leaked sensitive header %q value in output", header)
			}

			// Verify the header is redacted (shown as sensitive)
			if !strings.Contains(output, "(sensitive)") {
				t.Errorf("debugResponse did not redact header %q", header)
			}
		})
	}
}

